// Resolve file ID and determine type from search results
const searchResult = $('Search File by Name').first().json;

if (!searchResult.files || searchResult.files.length === 0) {
  return { json: { fileId: null, mimeType: null, error: `No file found in Google Drive with the name: "${$('Webhook').first().json.body.file_name}". Make sure the name matches exactly.` } };
}

const file = searchResult.files[0];
const SHEET_MIME = 'application/vnd.google-apps.spreadsheet';
const isSheet = file.mimeType === SHEET_MIME;

return { json: { fileId: file.id, fileName: file.name, mimeType: file.mimeType, isSheet } };

// Unified data parser: handles both Google Sheets API response and raw CSV text
// Outputs: { headers[], rows[][], csvSample(string), rowCount }

let headers = [];
let rows = [];

// Try Sheets API format first (from Fetch Sheet Data)
try {
  const sheetData = $('Fetch Sheet Data').first().json;
  if (sheetData.values && sheetData.values.length > 0) {
    headers = sheetData.values[0];
    rows = sheetData.values.slice(1);
  }
} catch(e) { /* Sheets node didn't run */ }

// If no Sheets data, try CSV export (from Export as CSV)
if (headers.length === 0) {
  try {
    const csvText = $('Export as CSV').first().json.data ||
                    $('Export as CSV').first().binary?.data?.toString() ||
                    String($('Export as CSV').first().json);
    const lines = csvText.trim().split('\n').filter(l => l.trim());
    if (lines.length > 0) {
      const parseCsv = (line) => {
        const result = [];
        let current = '';
        let inQuotes = false;
        for (let i = 0; i < line.length; i++) {
          const ch = line[i];
          if (ch === '"') { inQuotes = !inQuotes; }
          else if (ch === ',' && !inQuotes) { result.push(current.trim()); current = ''; }
          else { current += ch; }
        }
        result.push(current.trim());
        return result;
      };
      headers = parseCsv(lines[0]);
      rows = lines.slice(1).map(parseCsv);
    }
  } catch(e) { /* CSV also failed */ }
}

if (headers.length === 0) {
  return { json: { error: 'Could not parse file data. Make sure the file is a Google Sheet, CSV, or Excel file with data in it.' } };
}

// Build markdown table (first 50 rows max to keep it readable)
const displayRows = rows.slice(0, 50);
let mdTable = '| ' + headers.join(' | ') + ' |\n';
mdTable += '|' + headers.map(() => '---').join('|') + '|\n';
displayRows.forEach(row => {
  const padded = headers.map((_, i) => String(row[i] ?? '').replace(/\|/g, '/').replace(/\n/g, ' '));
  mdTable += '| ' + padded.join(' | ') + ' |\n';
});

// Build CSV sample (max 8000 chars) for Gemini
const csvLines = [headers.join(',')];
rows.slice(0, 200).forEach(row => {
  csvLines.push(headers.map((_, i) => `"${String(row[i] ?? '').replace(/"/g, '""')}"`).join(','));
});
const csvSample = csvLines.join('\n').substring(0, 8000);

return { json: { headers, rowCount: rows.length, mdTable, csvSample } };

