const parseData = $('Parse & Map Data').first().json;

// Parse errors
if (parseData.error) {
  return { json: { message: parseData.error, resultLink: '', chartData: null } };
}

const fileName = $('Extract File Info').first().json.fileName || $('Webhook').first().json.body.file_name;
const rowCount = parseData.rowCount;
const wantViz = $('Webhook').first().json.body.include_visualization;
const headers = parseData.headers || [];

// Short summary shown in the execution log card — no table, no big text
const shortMessage = `✅ Analysis complete for **${fileName}**\n**${rowCount} rows** across ${headers.length} columns analyzed.${wantViz === true || wantViz === 'true' ? '\n\nClick **Analyze Results** to view AI insights and interactive charts.' : ''}`;

let chartData = null;

if (wantViz === true || wantViz === 'true') {
  try {
    const geminiRaw = $('Gemini Analyze').first().json.candidates[0].content.parts[0].text;
    const cleanedText = geminiRaw.replace(/```json/g, '').replace(/```/g, '').trim();
    const geminiResult = JSON.parse(cleanedText);
    // Pack both insights text AND charts together into chartData
    chartData = JSON.stringify({
      insightsText: geminiResult.insights || '',
      charts: geminiResult.charts || []
    });
  } catch(e) {
    chartData = JSON.stringify({ insightsText: 'AI analysis could not be generated for this dataset.', charts: [] });
  }
}

return { json: { message: shortMessage, resultLink: '', chartData } };
